export async function build({presentation,input}){if(input.cleanBlank){const r=await presentation.inspect({kind:'slide',maxChars:5000});if(r.records.length===1&&r.records[0].textShapes===0)presentation.delete(r.records[0].id);}for(let i=input.start;i<input.end;i++)builders[i](presentation);return {slides:presentation.slides.items.length};}

const notes=[
  'Introdução e seção 1. A placa controla o inversor, mede RPM e publica telemetria. O motor da capa é uma ilustração funcional, sem representar um modelo ou uma montagem física específica.',
  'Introdução e seção 1. A operação local independe de Wi-Fi e Linker. As rotinas temporizadas ficam no display remoto. A placa recebe e executa comandos, enquanto mede o sensor e o inversor.',
  'Seções 1, 5.1 e 10. O diagrama resume os caminhos de comando e telemetria. Somente o loop usa Modbus e saídas. Somente LinkerMotor usa clientLinker. O servidor distribui a telemetria por broadcast ao grupo 1, sem exclusividade do ID 2.',
  'Seções 1 e 3. O sketch principal e controle_conexao.h definem o comportamento atual. backup.txt e backup_2.txt são referências antigas e não fazem parte da compilação. Os testes nativos não integram o firmware. As versões das bibliotecas não estão fixadas por um gerenciador no sketch.',
  'Seção 2. Imagem fornecida pelo projeto: images/montagem-referencia.png. O README informa sua origem na montagem motor_modbus_weg_bb.png. Ela mostra quatro dígitos. O código atual seleciona seis dígitos, e a tabela do firmware define a pinagem atual. O sketch não define o circuito de potência, o modelo exato do inversor nem a alimentação dos módulos.',
  'Seção 2. O sensor usa INPUT e interrupção RISING no GPIO34. O GPIO25 controla DE/RE conjuntamente. UART1 usa RX26 e TX27, a 9600 baud, 8N1, para o escravo 1. Serial local usa 115200 baud. As quatro saídas começam em LOW.',
  'Seção 2, direção do transceiver. preTxModbus coloca DE/RE em HIGH e espera 50 µs. postTxModbus chama flush, espera 500 µs e volta a LOW. Os callbacks atendem tanto leituras quanto escritas Modbus.',
  'Seção 3. Ambiente verificado: ESP32 Dev Module, esp32:esp32:esp32, Arduino-ESP32 3.3.12 e Tiny6. Ajustar ssid/password, TOKEN, ROOT_CA e cryptKey. Host e porta vêm de constantes da LinkerWX. ROOT_CA é identificado como ISRG Root X1. TARGET_DISPLAY_ID existe, mas não é usado no broadcast. A opção de quatro dígitos e cores antigos não foram validados nesta revisão.',
  'Seção 4. Serial inicia com espera de 1 s. Tiny6 mostra 888888 por 1 s e depois zero. setupModbus configura a UART e a biblioteca, sem consultar o inversor. Falhas na configuração, nas filas, na tarefa ou na proteção por watchdog desativam a rede e geram logs, sem espera infinita. O controle local continua.',
  'Seção 5. A Serial é atendida primeiro, seguida de no máximo um comando remoto por passagem. As transações Modbus e os pulsos de 150 ms são síncronos no loop. Os intervalos são condições mínimas de execução, sem garantia de periodicidade exata.',
  'Seção 5.1. LinkerMotor usa core 0, prioridade 1 e stack de 12288 bytes no ESP32 de dois cores. Em unicore, a tarefa não tem afinidade explícita. As filas não aguardam espaço ou dados. Elas copiam buffers fixos e estruturas, sem compartilhar String, ponteiros ou clientLinker. A fila de comandos é FIFO. Telemetria e estado sobrescrevem a única posição. Estados intermediários podem ser substituídos antes de o loop imprimir o log.',
  'Seções 3 e 5. O ciclo Modbus é contado desde o início da leitura anterior. O timeout do sensor é observado no próximo cálculo de RPM. A rede usa vTaskDelay de 10 ms, além de esperas internas. A primeira tentativa de conexão é imediata. O prazo de registro começa depois de begin retornar com transporte conectado.',
  'Seção 5.2. O TWDT usa esp_task_wdt_config_t e esp_task_wdt_reconfigure no core 3.3.12. Cada tarefa registra e alimenta sua própria inscrição. O loop alimenta ao final da passagem. A rede alimenta antes e depois da manutenção e após telemetria. O prazo comum de 240 s considera as esperas de rede, incluindo handshake TLS de até 120 s no core verificado. trigger_panic habilitado provoca reinicialização no ambiente documentado.',
  'Seção 6 e função detectPulseRPM no sketch. A ISR guarda o instante atual e o intervalo desde o pulso anterior. São necessários dois pulsos para o primeiro intervalo. Não há média ou filtro de ruído. A onda desenhada é uma ilustração funcional, sem escala elétrica.',
  'Seção 6 e função atualizarRPM. A cada pelo menos 1 s, o loop copia os tempos com interrupções brevemente desabilitadas. O intervalo deve ser maior que zero e de até 60.000.000 µs. A idade do último pulso deve ser de até 5 s. No timeout, o valor é zerado e o intervalo salvo é limpo. telemetryData.rpm e TM1637 são atualizados mesmo se o Modbus falhar.',
  'Seção 6. RPM = 60.000.000 / intervalo em microssegundos / pulsos por volta. O exemplo com 40.000 µs e um pulso por volta resulta em 1500 RPM. Com um pulso por volta, abaixo de 12 RPM o intervalo pode superar o timeout de 5 s e a indicação pode zerar entre pulsos.',
  'Seções 3, 4 e 6. Ilustração funcional do TM1637 de seis dígitos. SEIS_DIGITOS seleciona TM1637TinyDisplay6. O teste mostra 888888 por 1 s e depois zero. A leitura 1500 é ilustrativa. O código usa showNumber com zeros à esquerda desabilitados. Quatro dígitos exigem TM1637Display e não foram validados nesta revisão.',
  'Seções 7.1 e 10.2 e função pollModbusTelemetry. Uma leitura bem-sucedida converte escalas, captura rpmAtual, atualiza lastUpdateMs e telemetryDataFresh e disponibiliza uma cópia para a rede. Falhas imprimem o erro, preservam os valores anteriores e não produzem amostra nova.',
  'Seção 7.1. Os endereços são valores hexadecimais passados diretamente ao ModbusMaster, sem conversão para referências 4xxxx. O bloco contém nove registradores. 0x7006 e 0x7007 são lidos e ignorados. O firmware não identifica o inversor nem decodifica os bits do estado de saídas.',
  'Seções 7.2 e 8.2. As escritas usam writeSingleRegister. START escreve 1, REVERSE 2, STOP 6 e EMERGENCY 5 em 0x2000. O pulso correspondente só acontece após sucesso. SET2000=N faz escrita direta sem pulso. A frequência positiva usa Hz multiplicado por 100 em 0x1000, com conversão para uint16_t.',
  'Seção 8.1. Na Serial, enviar uma linha com LF ou CRLF. O leitor ignora CR e processa LF. Pela rede, aceita-se comando direto ou prefixo cmd=/CMD=. handleRemoteCommand remove prefixo e espaços e copia o texto para a fila. O leitor Serial local não remove esse prefixo. Nenhum callback de rede executa Modbus.',
  'Seção 8.2. O parser remove espaços externos e normaliza o nome. HELP e RPMSTATUS retornam antes de verificar se Modbus foi inicializado. Os demais caminhos exigem modbusInitialized. STATUS faz consultas sem pulso. Comandos desconhecidos ou Modbus não inicializado geram diagnóstico na Serial.',
  'Seção 8.2. START, STOP, REVERSE e EMERGENCY chamam sendCommandToDrive. Somente após sucesso, executarAcaoMotor seleciona o GPIO e gera HIGH por 150 ms, seguido de LOW. Uma falha Modbus impede o pulso, inclusive para EMERGENCY. A onda representa a temporização lógica, não um circuito de potência.',
  'Seções 7.2 e 8.3 e função processSerialCommand. Trecho selecionado do caminho numérico. O comando usa ponto decimal, por exemplo 45.5. A conversão para uint16_t ocorre depois de multiplicar por 100. Não há teto de frequência definido pela aplicação. SET2000=N usa toInt e escreve diretamente em 0x2000, sem pulso.',
  'Seção 8.3. toFloat e toInt não validam a entrada completa. Zero e números negativos não são aceitos como frequência. Na Serial, mais de 100 caracteres limpa o buffer e o restante da mesma linha continua sendo recebido. O remoto descarta textos normalizados acima de 100 caracteres. A fila cheia descarta o comando novo sem esperar espaço. Resultados e erros são impressos apenas na Serial.',
  'Seções 1 e 9.1. Identidade da placa: grupo 1, ID 1. Telemetria usa broadcastText com REQ_ACK. onRECV registra a origem, mas a aplicação não a compara com uma lista de remetentes. RECV_OK é confirmação do servidor, sem comprovar execução física nem atualização de tela. O enquadramento e a codificação dos pacotes pertencem à biblioteca.',
  'Seção 9.3. OFFLINE libera a primeira tentativa imediatamente. Depois de falha, aguarda 60 s. begin pode bloquear somente a tarefa de rede. Com socket aberto, AGUARDANDO_REGISTRO usa poll para receber HI/AGAIN em até 10 s. Perder registro com socket ainda aberto retorna a essa espera. Falha de configuração ou de inscrição no watchdog publica DESATIVADA e termina a tarefa, preservando o controle local.',
  'Seções 9.1 e 9.3. A espera de 60 s começa após encerrar a sessão da tentativa que falhou. O exemplo de 15 s de tentativa é seguido de mais 60 s. Não há tentativas agendadas sobrepostas. O controlador usa diferenças uint32_t com millis, incluindo rollover. A biblioteca não foi modificada: poll pode fazer tentativa interna de Wi-Fi, e o driver pode reassociar automaticamente.',
  'Seção 10.1. Valores ilustrativos, na ordem de gerarPacoteTelemetriaA. Fa, fs, vdc, vs, i e tq usam uma casa decimal. Edo e rpm são inteiros decimais. Os registradores de frequência têm resolução de 0,01 Hz, mas o pacote usa uma casa decimal. Não há JSON, prefixo cmd= ou timestamp. lastUpdateMs permanece local.',
  'Seção 10.2. A fila mantém apenas a última amostra. A tarefa online verifica idade de até 5 s, registro há mais de 300 ms e intervalo de pelo menos 1 s entre tentativas. Sucesso consome a amostra privada. Falha mantém a cópia até reenvio, substituição por amostra nova ou expiração. Isso não bloqueia o loop local.',
  'Seção 10.2 e funções sendTelemetryData e enviarTelemetriaNaRede. xQueueOverwrite publica uma cópia sem esperar. telemetryDataFresh é limpo quando a cópia entra na fila. Leituras seguintes substituem a amostra, inclusive offline. Não há histórico. A tarefa de rede usa um snapshot privado. telemetryReady existe como helper, mas não é chamado pelo fluxo atual.',
  'Seções 7.3, 8 e 12. STATUS faz quatro consultas separadas e imprime também o RPM armazenado. 0x703D aparece em inteiro e binário, 0x703E em inteiro, 0x7000 é dividido por 100 e 0x7004 por 10. O firmware não decodifica bits nem códigos. RPMSTATUS informa nível GPIO, intervalo e instantes da última captura e da consulta, permitindo comparar a idade. A saída fica na Serial mesmo para comandos remotos.',
  'Seções 9.2 e 12. Conferir HELP, RPMSTATUS, STATUS, HI/AGAIN, Modbus OK, SEND e RECV_OK. ERR 1 fecha a sessão para reconectar. ERR 10 registra desconexão forçada e a tarefa agenda nova tentativa ao detectar o socket fechado. ERR 11 indica token inválido para o destino. WELCOME, UNKNOWN, DEST e onError geram logs. Falhas de watchdog devem ser investigadas pela tarefa e etapa informadas.',
  'Seção 12, validação em 13/11/2026. Oito cenários passaram com Clang 18/C++11. O sketch compilou para esp32:esp32:esp32 com core 3.3.12: 1.026.888 bytes de flash, 78%, e 48.960 bytes globais, 14%. Houve aviso existente de IRAM_ATTR em detectPulseRPM, sem erro de compilação. Os hashes da LinkerWX permaneceram iguais. Esses resultados documentados não validam comunicação física, escalonamento ou watchdog na placa.',
  'Seção 11. Além das funções da tabela, inicializarWatchdog e iniciarTarefaRede preparam a proteção e a rede. mostrarEstadoRede imprime mudanças publicadas. configurarPinosControle e configurarSensorRPM iniciam os GPIOs. showStatusDrive executa o diagnóstico. telemetryReady permanece sem chamadas.',
  'Seção 12, limites atuais. O firmware não implementa parada automática ao perder Wi-Fi, TLS ou telemetria. EMERGENCY passa pelo mesmo caminho de software e Modbus. O nome não define um circuito independente de emergência. As rotinas temporizadas ficam no display. Não há resposta dedicada de execução ao remetente, persistência de configurações ou histórico de medições. Falhas de leitura preservam os valores anteriores.'
];
export async function review({presentation}){
  for(let i=0;i<notes.length;i++)presentation.slides.getItem(i).speakerNotes.text=`Fonte: ${ROOT}README.md, revisão de 13/11/2026.\n${notes[i]}`;
  const all=(await presentation.inspect({kind:'shape,textbox',maxChars:250000})).records;
  function find(index,text){const r=all.find(r=>r.slideIndex===index&&r.text===text);if(!r)throw new Error('Texto ausente '+text);return presentation.resolve(r.id);}
  let t=find(10,'Telemetria: 1 posição\nloop para rede');t.position={...t.position,top:313.5};
  t=find(14,'não');t.position={...t.position,top:300};
  const codeSlide=presentation.slides.getItem(23);
  const old=all.filter(r=>r.slideIndex===23&&r.position?.top===285);
  const oldText=all.find(r=>r.slideIndex===23&&r.text?.startsWith('float freq = comando.toFloat();'));
  presentation.delete([...old.map(r=>r.id),oldText.id]);
  code(codeSlide,'float freq = comando.toFloat();\nif (freq > 0.0f) {\n  uint16_t freqRaw = (uint16_t)(freq * 100.0f);\n  bool ok = writeRegisterWithMsg(0x1000, freqRaw,\n      "Setpoint de frequencia atualizado",\n      "Falha ao escrever frequencia");\n}',58,264,1164,266,24);
  return {slides:presentation.slides.items.length,notes:notes.length};
}

